        if sku in sku_weights and sku_weights[sku] != weight:
            raise ValueError(f"SKU {sku} has inconsistent unit weights")
        sku_weights[sku] = weight
        merged_skus[sku] = merged_skus.get(sku, 0) + qty

    items: List[Tuple[str, int]] = []
    chunk_to_info: Dict[str, Tuple[str, int]] = {}

    chunk_id = 0
    for sku, total_qty in merged_skus.items():
        unit_weight = sku_weights[sku]
        if unit_weight > max_parcel_grams:
            raise ValueError(f"Unit weight of {sku} exceeds max_parcel_grams")

        remaining_qty = total_qty
        while remaining_qty > 0:
            qty_in_chunk = min(remaining_qty, max_parcel_grams // unit_weight)
            weight_of_chunk = qty_in_chunk * unit_weight
            cid = f"chunk_{chunk_id}"
            items.append((cid, weight_of_chunk))
            chunk_to_info[cid] = (sku, qty_in_chunk)
            remaining_qty -= qty_in_chunk
            chunk_id += 1

    bins = first_fit_decreasing(items, max_parcel_grams)

    parcels: List[Dict[str, int]] = []
    for bin_items in bins:
        parcel: Dict[str, int] = {}
        for cid, weight in bin_items:
            sku, qty = chunk_to_info[cid]
            parcel[sku] = parcel.get(sku, 0) + qty
        parcels.append(parcel)

    return parcels
