    for sku, qty, w in lines:
        if qty <= 0 or w <= 0:
            raise ValueError("qty and unit weight must be > 0")
        if sku in weights and weights[sku] != w:
            raise ValueError(f"SKU {sku} has inconsistent unit weights")
        weights[sku] = w
        merged[sku] = merged.get(sku, 0) + qty

    items: List[Tuple[str, int]] = []
    chunk_map: Dict[str, Tuple[str, int]] = {}
    cid = 0
    for sku, qty in merged.items():
        w = weights[sku]
        if w > max_parcel_grams:
            raise ValueError(f"Unit weight of {sku} exceeds max_parcel_grams")

        if qty * w <= max_parcel_grams:
            cid_str = f"c{cid}"
            items.append((cid_str, qty * w))
            chunk_map[cid_str] = (sku, qty)
            cid += 1
        else:
            for _ in range(qty):
                cid_str = f"c{cid}"
                items.append((cid_str, w))
                chunk_map[cid_str] = (sku, 1)
                cid += 1

    bins = first_fit_decreasing(items, max_parcel_grams)
    res: List[Dict[str, int]] = []
    for b in bins:
